    "You can import local Shards and Standard ships once, before your first account game. Pi purchases and records are excluded. Otherwise, local items stay on this device.": "Tu peux importer les Shards et vaisseaux standard locaux une fois avant ta première partie avec le compte. Achats Pi et records exclus. Sinon, les objets restent sur cet appareil.",
