    "Blocks the next hit": "Bloqueia o próximo impacto",
    "Clears enemies and shots": "Elimina inimigos e projéteis",
    "Freezes enemies for 7s": "Imobiliza inimigos por 7 s",
    "Absorbs the next hit for up to 20 seconds.": "Absorve o próximo impacto por até 20 segundos.",
    "Powers each shot up to deal two damage for 20 seconds.": "Cada disparo causa 2 de dano durante 20 segundos.",
    "Raises your weapon by one level for 20 seconds, up to level 5.": "Sobe a arma um nível por 20 segundos, até ao nível 5.",
    "Sets automatic fire to its fast cadence for 20 seconds.": "Acelera o disparo automático durante 20 segundos.",
    "Tap to switch weapon. Hold for weapon menu.": "Toca para mudar de arma. Mantém premido para o menu.",
    "Move with one thumb; activate power-ups with the other.": "Move com um polegar; ativa os reforços com o outro.",
    "Your ship fires automatically. Move to dodge and line up your shots.": "A nave dispara automaticamente. Move para desviar e alinhar os tiros.",
    "You start with three hearts. The mission ends when all are lost.": "Começas com três vidas. A missão termina quando as perdes todas.",
    "Each level has nine visible Blocks, then a boss fight and a bonus round.": "Cada nível tem nove blocos, depois um chefe e uma ronda bónus.",
    "Fly through glowing drops to collect boosts that activate immediately.": "Voa sobre os itens brilhantes para ativar os reforços imediatamente.",
    "Connect your Pi account to see your saved loadout.": "Liga a conta Pi para ver o equipamento guardado.",
    "Personal best saved.": "Recorde pessoal guardado.",
    "Saving personal best…": "A guardar recorde pessoal…",
    "Could not sync personal best. Local best is saved.": "Não foi possível sincronizar o recorde. O recorde local está guardado.",
    "No records yet. Complete a mission to be first.": "Ainda sem recordes. Conclui uma missão para seres o primeiro.",
    "Not enough Shards yet. Earn them by defeating Cryptoids.": "Shards insuficientes. Ganha mais derrotando Cryptoids.",
    "Save bonus for a later mission": "Guardar bónus para outra missão",
    "Your current mission will be replaced. Your balance and owned ships remain available.": "A missão atual será substituída. O saldo e as naves adquiridas permanecem.",
    "Your current mission will end. Your records will be saved locally.": "A missão atual termina. Os recordes serão guardados neste dispositivo.",
    "Account rewards notice": "As recompensas são guardadas na conta Pi imediatamente. Testes de administrador não contam.",
    "Mainnet equipment notice": "Novos estágios avançados, elite, blindagem e reforços iniciais ficam disponíveis no Mainnet. Os já adquiridos continuam utilizáveis.",
    "Mainnet progress notice": "A coleção Mainnet começa do zero e fica guardada na conta. O progresso Testnet é separado.",
    "Mainnet inventory notice": "No Mainnet, Shards e naves compradas começam do zero. O inventário Testnet é separado.",
    "Testnet progress notice": "As recompensas Testnet são só para testes e não passam para Mainnet. No Mainnet, começam do zero e são guardadas na conta.",
    "Testnet inventory notice": "Shards e compras de naves padrão no Testnet são para testes. Não passam para Mainnet; lá o saldo e a frota comprada começam do zero.",
