    "Starter price notice": "A nave inicial é grátis. O preço é para uma nave adicional.",
    "Twin rules": "Dois disparos paralelos. Ativo por 2 minutos após ativar.",
    "Rapid twin rules": "Dois disparos com fogo automático mais rápido. Ativo por 2 minutos.",
