    "Rapid rules": "Ativa fogo automático mais rápido no botão lateral, por 60 segundos.",
    "Overdrive rules": "Ativa disparos mais fortes no botão lateral, por 60 segundos.",
    "Nova rules": "Uma utilização por missão. Elimina inimigos e tiros visíveis; causa 18 de dano ao chefe.",
    "EMP rules": "Uma utilização por missão. Imobiliza inimigos e tiros por 7 segundos; elimina os tiros presentes.",
    "Reinforced hull rules": "Blindagem permanente: +1 vida no início de cada missão, sem escudo.",
    "Titanium rules": "Blindagem permanente: mais 2 vidas em cada missão. Soma-se ao casco reforçado.",
    "Advanced rules": "Permanente: fogo duplo e proteção contra 1 projétil por vida. Colisões com naves requerem escudo.",
    "Elite rules": "Permanente: laser duplo mais forte e proteção contra 2 projéteis por vida. Colisões requerem escudo. Requer estágio avançado.",
