    "Save changed. Reload and choose again.": "O jogo guardado mudou. Recarrega e escolhe novamente.",
    "Game saved. Offline backup unavailable.": "Jogo guardado. Cópia offline indisponível.",
    "Completed sections stay saved in your Pi account. An unfinished section restarts when you resume.": "As secções concluídas ficam na conta Pi. Uma secção inacabada recomeça ao continuar.",
    "Start with account inventory": "Começar com o inventário da conta",
    "Import local inventory and start": "Importar inventário local e começar",
    "Use confirmed save": "Usar jogo confirmado",
    "Completed sections stay saved. Your remaining lives are kept when you leave.": "As secções concluídas e vidas restantes ficam guardadas ao sair.",
    "Your completed sections and remaining lives stay saved. The unfinished section restarts; its points and Shards are discarded.": "Secções concluídas e vidas restantes ficam guardadas. A secção inacabada recomeça; os seus pontos e Shards são descartados.",
    "Admin test mode: purchases and records are not saved.": "Modo de teste: compras e recordes não são guardados.",
    "Import local inventory once": "Importar inventário local uma vez",
    "Assign this local inventory to my Pi account.": "Associar este inventário local à minha conta Pi.",
    "Could not verify the Pi session. Please retry.": "Não foi possível verificar a sessão Pi. Tenta novamente.",
    "Completing secure Pi sign-in…": "A concluir entrada segura com Pi…",
    "Sign-in failed": "Falha ao entrar",
    "Pi sign-in was not approved.": "A entrada Pi não foi autorizada.",
    "Pi sign-in was cancelled or expired.": "A entrada Pi foi cancelada ou expirou.",
    "Signed in. Opening Cryptoid Evolution…": "Sessão iniciada. A abrir Cryptoid Evolution…",
