    "Save failed. Please retry.": "Falha ao guardar. Tenta novamente.",
    "Save unconfirmed. Check connection and sign-in.": "Gravação não confirmada. Verifica a ligação e a sessão.",
    "Save unconfirmed. Automatic retry pending.": "Gravação não confirmada. Será repetida automaticamente.",
    "Save failed. Game paused. Retry.": "Falha ao guardar. O jogo fica em pausa. Tenta novamente.",
    "Save unconfirmed. Retry or use confirmed save.": "Gravação não confirmada. Tenta novamente ou usa o jogo confirmado.",
    "Save unavailable. Please retry.": "Jogo guardado indisponível. Tenta novamente.",
    "Save unavailable. Local data unchanged. Retry sign-in.": "Jogo indisponível. Dados locais intactos. Entra novamente.",
    "Save unavailable. Local data unchanged. Purchases locked.": "Jogo indisponível. Dados locais intactos. Compras bloqueadas.",
    "Refresh inventory. Confirmed purchases will not repeat.": "Atualiza o inventário. Compras confirmadas não serão repetidas.",
    "Import unconfirmed. Check account inventory.": "Importação não confirmada. Verifica o inventário da conta.",
    "Pending data set aside. Using the confirmed account save.": "Dados pendentes separados. É usado o jogo confirmado.",
    "You can import local Shards and Standard ships once, before your first account game. Pi purchases and records are excluded. Otherwise, local items stay on this device.": "Podes importar Shards e naves padrão locais uma vez antes do primeiro jogo da conta. Compras Pi e recordes ficam excluídos. Caso contrário, os itens ficam neste dispositivo.",
    "Grey Scout is free; nine Standard hulls cost Shards. Other hulls are currently locked.": "Grey Scout é grátis; nove cascos padrão custam Shards. Os restantes estão bloqueados.",
    "Available only as a weapon pickup.": "Disponível apenas como arma recolhida no jogo.",
    "An older weapon selection is saved but no longer activates automatically. Every mission starts with the single laser.": "Uma seleção de arma anterior está guardada, mas já não ativa automaticamente. Cada missão começa com o laser simples.",
    "1 Shard per target. Completion bonus added immediately.": "1 Shard por alvo. Bónus final adicionado de imediato.",
    "Block": "Bloco",
