    "Resume available at section {section} ({phase}).": "Podes continuar na secção {section} ({phase}).",
    "Resume at section {section} · {phase} · {hearts} lives · {score} points.": "Continuar na secção {section} · {phase} · {hearts} vidas · {score} pontos.",
    "Payment could not be confirmed. Check your account and retry.": "Pagamento não confirmado. Verifica a conta e tenta novamente.",
