    "Absorbs the next hit for up to 20 seconds.": "Assorbe il prossimo colpo per un massimo di 20 secondi.",
    "Powers each shot up to deal two damage for 20 seconds.": "Ogni colpo infligge 2 danni per 20 secondi.",
    "Raises your weapon by one level for 20 seconds, up to level 5.": "Aumenta l’arma di un livello per 20 secondi, fino al livello 5.",
