    "Tap to switch weapon. Hold for weapon menu.": "Tocca per cambiare arma. Tieni premuto per il menu.",
    "Move with one thumb; activate power-ups with the other.": "Muoviti con un pollice; attiva i potenziamenti con l’altro.",
    "Your ship fires automatically. Move to dodge and line up your shots.": "La nave spara automaticamente. Muoviti per schivare e mirare.",
    "You start with three hearts. The mission ends when all are lost.": "Inizi con tre vite. La missione finisce quando le perdi tutte.",
    "Each level has nine visible Blocks, then a boss fight and a bonus round.": "Ogni livello ha nove blocchi, poi un boss e un round bonus.",
    "Fly through glowing drops to collect boosts that activate immediately.": "Vola sugli oggetti luminosi per attivare subito i potenziamenti.",
