    "Account rewards notice": "Le ricompense sono salvate subito nell’account Pi. Le prove amministrative non contano.",
    "Mainnet equipment notice": "Nuovi stadi avanzati, élite, corazze e bonus iniziali saranno disponibili su Mainnet. Quelli già posseduti restano utilizzabili.",
