    "Refresh inventory. Confirmed purchases will not repeat.": "Aggiorna l’inventario. Gli acquisti confermati non saranno ripetuti.",
    "Import unconfirmed. Check account inventory.": "Importazione non confermata. Controlla l’inventario dell’account.",
    "Pending data set aside. Using the confirmed account save.": "Dati in sospeso accantonati. Si usa il salvataggio confermato.",
    "You can import local Shards and Standard ships once, before your first account game. Pi purchases and records are excluded. Otherwise, local items stay on this device.": "Puoi importare Shards e navi standard locali una volta prima della prima partita con l’account. Acquisti Pi e record sono esclusi. Altrimenti gli oggetti restano su questo dispositivo.",
    "Grey Scout is free; nine Standard hulls cost Shards. Other hulls are currently locked.": "Grey Scout è gratis; nove scafi standard costano Shards. Gli altri sono bloccati.",
