    "Absorbs the next hit for up to 20 seconds.": "En fazla 20 saniye boyunca sonraki darbeyi engeller.",
    "Powers each shot up to deal two damage for 20 seconds.": "Her atış 20 saniye boyunca 2 hasar verir.",
    "Raises your weapon by one level for 20 seconds, up to level 5.": "Silahı 20 saniyeliğine bir seviye yükseltir; en fazla seviye 5.",
    "Sets automatic fire to its fast cadence for 20 seconds.": "Otomatik ateşi 20 saniye hızlandırır.",
    "Tap to switch weapon. Hold for weapon menu.": "Silah değiştirmek için dokun. Menü için basılı tut.",
    "Move with one thumb; activate power-ups with the other.": "Bir başparmakla hareket et; diğeriyle güçlendirmeleri aç.",
    "Your ship fires automatically. Move to dodge and line up your shots.": "Gemin otomatik ateş eder. Kaçmak ve nişan almak için hareket et.",
    "You start with three hearts. The mission ends when all are lost.": "Üç canla başlarsın. Hepsi bitince görev sona erer.",
    "Each level has nine visible Blocks, then a boss fight and a bonus round.": "Her seviyede dokuz blok, ardından bölüm sonu savaşı ve bonus turu vardır.",
    "Fly through glowing drops to collect boosts that activate immediately.": "Parlayan öğelerden geçerek güçlendirmeleri hemen etkinleştir.",
