    "No records yet. Complete a mission to be first.": "Henüz rekor yok. İlk olmak için bir görevi bitir.",
    "Not enough Shards yet. Earn them by defeating Cryptoids.": "Yeterli Shards yok. Cryptoids yenerek kazan.",
    "Save bonus for a later mission": "Bonusu sonraki göreve sakla",
    "Your current mission will be replaced. Your balance and owned ships remain available.": "Mevcut görev değiştirilecek. Bakiyen ve gemilerin korunur.",
    "Your current mission will end. Your records will be saved locally.": "Mevcut görev bitecek. Rekorlar bu cihaza kaydedilir.",
    "Account rewards notice": "Ödüller Pi hesabına hemen kaydedilir. Yönetici testleri sayılmaz.",
    "Mainnet equipment notice": "Yeni gelişmiş ve seçkin aşamalar, zırh ve başlangıç güçlendirmeleri Mainnet’te açılacak. Sahip olunanlar kullanılabilir.",
    "Mainnet progress notice": "Mainnet koleksiyonu sıfırdan başlar ve hesaba kaydedilir. Testnet ilerlemesi ayrıdır.",
    "Mainnet inventory notice": "Mainnet’te Shards ve alınan gemiler sıfırdan başlar. Testnet envanteri ayrıdır.",
    "Testnet progress notice": "Testnet ödülleri test içindir ve Mainnet’e taşınmaz. Mainnet’te sıfırdan başlar ve hesapta kalır.",
    "Testnet inventory notice": "Testnet Shards ve standart gemi alımları test içindir. Mainnet’e taşınmaz; bakiye ve alınan filo sıfırdan başlar.",
    "Data unavailable. Retry.": "Veriler yok. Yeniden dene.",
    "Local rewards notice": "Yerel ödüller bu cihazda kalır. Yeni ödülleri Pi hesabına kaydetmek için giriş yap.",
    "Starter price notice": "Başlangıç gemisi ücretsizdir. Fiyat ek gemi içindir.",
    "Twin rules": "İki paralel atış. Etkinleştirmeden sonra 2 dakika çalışır.",
    "Rapid twin rules": "Daha hızlı otomatik ateşle iki atış. 2 dakika etkin.",
    "Triple rules": "Üç yayılan atış. Etkinleştirmeden sonra 2 dakika çalışır.",
    "Plasma rules": "Üç daha güçlü plazma atışı. 2 dakika etkin.",
    "Shield rules": "Etkinleştirmeden sonra 60 saniye koruma. Geçişlerde süre durur.",
    "Rapid rules": "Yan düğmeyle 60 saniye hızlı otomatik ateş aç.",
    "Overdrive rules": "Yan düğmeyle 60 saniye daha güçlü atış aç.",
    "Nova rules": "Görev başına bir kez. Görünen düşmanları ve atışları temizler; bölüm sonuna 18 hasar verir.",
    "EMP rules": "Görev başına bir kez. Düşmanları ve ateşlerini 7 saniye durdurur; mevcut atışları temizler.",
    "Reinforced hull rules": "Kalıcı zırh: her görev başında +1 can, kalkan gerekmez.",
    "Titanium rules": "Kalıcı zırh: her görevde ek 2 can. Güçlendirilmiş gövdeye eklenir.",
    "Advanced rules": "Kalıcı: çift ateş ve can başına 1 mermi koruması. Gemi çarpışmaları kalkan gerektirir.",
    "Elite rules": "Kalıcı: güçlü çift lazer ve can başına 2 mermi koruması. Çarpışmalar kalkan gerektirir. Gelişmiş aşama gerekir.",
