    "Game saved. Offline backup unavailable.": "Oyun kaydedildi. Çevrimdışı yedek yok.",
    "Completed sections stay saved in your Pi account. An unfinished section restarts when you resume.": "Tamamlanan bölümler Pi hesabında kalır. Bitmemiş bölüm devam ederken yeniden başlar.",
