    "Completed sections stay saved. Your remaining lives are kept when you leave.": "Tamamlanan bölümler ve kalan canların çıkarken korunur.",
    "Your completed sections and remaining lives stay saved. The unfinished section restarts; its points and Shards are discarded.": "Tamamlanan bölümler ve kalan canlar kaydedilir. Bitmemiş bölüm yeniden başlar; o bölümün puanları ve Shards kaybolur.",
    "Admin test mode: purchases and records are not saved.": "Yönetici test modu: satın alımlar ve rekorlar kaydedilmez.",
