    "Save unconfirmed. Check connection and sign-in.": "Kayıt onaylanmadı. Bağlantıyı ve girişi kontrol et.",
    "Save unconfirmed. Automatic retry pending.": "Kayıt onaylanmadı. Otomatik yeniden deneme bekliyor.",
    "Save failed. Game paused. Retry.": "Kayıt başarısız. Oyun duraklatıldı. Yeniden dene.",
    "Save unconfirmed. Retry or use confirmed save.": "Kayıt onaylanmadı. Yeniden dene veya onaylanmış kaydı kullan.",
    "Save unavailable. Please retry.": "Kayıt kullanılamıyor. Yeniden dene.",
    "Save unavailable. Local data unchanged. Retry sign-in.": "Kayıt yok. Yerel veriler değişmedi. Yeniden giriş yap.",
    "Save unavailable. Local data unchanged. Purchases locked.": "Kayıt yok. Yerel veriler değişmedi. Satın alımlar kilitli.",
    "Refresh inventory. Confirmed purchases will not repeat.": "Envanteri yenile. Onaylı satın alımlar tekrarlanmaz.",
    "Import unconfirmed. Check account inventory.": "Aktarım onaylanmadı. Hesap envanterini kontrol et.",
    "Pending data set aside. Using the confirmed account save.": "Bekleyen veriler ayrıldı. Onaylanmış hesap kaydı kullanılıyor.",
    "You can import local Shards and Standard ships once, before your first account game. Pi purchases and records are excluded. Otherwise, local items stay on this device.": "İlk hesap oyunundan önce yerel Shards ve standart gemileri bir kez aktarabilirsin. Pi satın alımları ve rekorlar aktarılmaz. Aksi halde öğeler bu cihazda kalır.",
    "Grey Scout is free; nine Standard hulls cost Shards. Other hulls are currently locked.": "Grey Scout ücretsizdir; dokuz standart gövde Shards ile alınır. Diğerleri kilitlidir.",
    "Available only as a weapon pickup.": "Yalnızca oyunda toplanan silah olarak kullanılabilir.",
    "An older weapon selection is saved but no longer activates automatically. Every mission starts with the single laser.": "Eski silah seçimi kaydedildi ama otomatik etkinleşmez. Her görev tek lazerle başlar.",
    "1 Shard per target. Completion bonus added immediately.": "Hedef başına 1 Shard. Tamamlama bonusu hemen eklenir.",
