    "Account inventory saved": "Hesap envanteri kaydedildi",
    "Resume available at section {section} ({phase}).": "{section}. bölümden ({phase}) devam edilebilir.",
    "Resume at section {section} · {phase} · {hearts} lives · {score} points.": "{section}. bölümden devam · {phase} · can: {hearts} · puan: {score}.",
    "Payment could not be confirmed. Check your account and retry.": "Ödeme onaylanmadı. Hesabını kontrol et ve yeniden dene.",
