    "Overdrive rules": "Aktiviraj snažnije metke bočnim gumbom na 60 sekundi.",
    "Nova rules": "Jednom po misiji. Uklanja vidljive neprijatelje i metke; nanosi šefu 18 štete.",
    "EMP rules": "Jednom po misiji. Zaustavlja neprijatelje i paljbu na 7 sekundi; uklanja postojeće metke.",
    "Reinforced hull rules": "Trajni oklop: +1 život na početku svake misije, bez štita.",
    "Titanium rules": "Trajni oklop: još 2 života u svakoj misiji. Dodaje se ojačanom trupu.",
    "Advanced rules": "Trajno: dvostruka paljba i zaštita od 1 projektila po životu. Sudari s brodovima trebaju štit.",
    "Elite rules": "Trajno: jači dvostruki laser i zaštita od 2 projektila po životu. Sudari trebaju štit. Potrebna napredna faza.",
