    "Your completed sections and remaining lives stay saved. The unfinished section restarts; its points and Shards are discarded.": "Završeni dijelovi i životi ostaju spremljeni. Nedovršeni dio počinje ponovno; njegovi bodovi i Shards se odbacuju.",
