    "Save unconfirmed. Check connection and sign-in.": "Spremanje nije potvrđeno. Provjeri vezu i prijavu.",
    "Save unconfirmed. Automatic retry pending.": "Spremanje nije potvrđeno. Slijedi automatski pokušaj.",
    "Save failed. Game paused. Retry.": "Spremanje nije uspjelo. Igra je pauzirana. Pokušaj ponovno.",
    "Save unconfirmed. Retry or use confirmed save.": "Spremanje nije potvrđeno. Pokušaj ponovno ili koristi potvrđenu igru.",
    "Save unavailable. Please retry.": "Spremljena igra nije dostupna. Pokušaj ponovno.",
    "Save unavailable. Local data unchanged. Retry sign-in.": "Igra nije dostupna. Lokalni podaci nepromijenjeni. Prijavi se ponovno.",
    "Save unavailable. Local data unchanged. Purchases locked.": "Igra nije dostupna. Lokalni podaci nepromijenjeni. Kupnje zaključane.",
    "Refresh inventory. Confirmed purchases will not repeat.": "Osvježi inventar. Potvrđene kupnje neće se ponoviti.",
    "Import unconfirmed. Check account inventory.": "Uvoz nije potvrđen. Provjeri inventar računa.",
    "Pending data set aside. Using the confirmed account save.": "Podaci na čekanju odloženi. Koristi se potvrđena igra.",
    "You can import local Shards and Standard ships once, before your first account game. Pi purchases and records are excluded. Otherwise, local items stay on this device.": "Lokalni Shards i standardni brodovi mogu se uvesti jednom prije prve igre računa. Pi kupnje i rekordi nisu uključeni. Inače predmeti ostaju na uređaju.",
    "Grey Scout is free; nine Standard hulls cost Shards. Other hulls are currently locked.": "Grey Scout je besplatan; devet standardnih trupova košta Shards. Ostali su zaključani.",
    "Available only as a weapon pickup.": "Dostupno samo kao oružje koje se skuplja u igri.",
    "An older weapon selection is saved but no longer activates automatically. Every mission starts with the single laser.": "Stariji odabir oružja spremljen je, ali se ne aktivira automatski. Svaka misija počinje jednim laserom.",
    "1 Shard per target. Completion bonus added immediately.": "1 Shard po meti. Završni bonus dodaje se odmah.",
