    "Powers each shot up to deal two damage for 20 seconds.": "Každá střela způsobí 2 poškození po dobu 20 sekund.",
    "Raises your weapon by one level for 20 seconds, up to level 5.": "Zvýší zbraň o úroveň na 20 sekund, nejvýše na úroveň 5.",
    "Sets automatic fire to its fast cadence for 20 seconds.": "Zrychlí automatickou palbu na 20 sekund.",
