    "Move with one thumb; activate power-ups with the other.": "Ovládej jedním palcem; druhým aktivuj posílení.",
    "Your ship fires automatically. Move to dodge and line up your shots.": "Loď střílí automaticky. Pohybuj se pro uhýbání a míření.",
    "You start with three hearts. The mission ends when all are lost.": "Začínáš se třemi životy. Po ztrátě všech mise končí.",
    "Each level has nine visible Blocks, then a boss fight and a bonus round.": "Každá úroveň má devět bloků, potom bosse a bonusové kolo.",
    "Fly through glowing drops to collect boosts that activate immediately.": "Proleť zářícími předměty a ihned aktivuj posílení.",
    "Connect your Pi account to see your saved loadout.": "Připoj účet Pi a zobraz uloženou výbavu.",
