    "Saving personal best…": "Ukládání osobního rekordu…",
    "Could not sync personal best. Local best is saved.": "Rekord nelze synchronizovat. Místní rekord je uložen.",
    "No records yet. Complete a mission to be first.": "Zatím žádné rekordy. Dokonči misi jako první.",
    "Not enough Shards yet. Earn them by defeating Cryptoids.": "Nedostatek Shards. Získej je porážením Cryptoids.",
    "Save bonus for a later mission": "Uchovat bonus pro pozdější misi",
    "Your current mission will be replaced. Your balance and owned ships remain available.": "Současná mise bude nahrazena. Zůstatek a vlastněné lodě zůstanou.",
    "Your current mission will end. Your records will be saved locally.": "Současná mise skončí. Rekordy se uloží do zařízení.",
    "Account rewards notice": "Odměny se ihned ukládají do účtu Pi. Testy správce se nepočítají.",
    "Mainnet equipment notice": "Nové pokročilé a elitní stupně, pancíř a úvodní posílení budou v Mainnet. Vlastněné zůstávají použitelné.",
    "Mainnet progress notice": "Sbírka Mainnet začíná od nuly a ukládá se do účtu. Postup Testnet je oddělený.",
    "Mainnet inventory notice": "V Mainnet začínají Shards a koupené lodě od nuly. Inventář Testnet je oddělený.",
    "Testnet progress notice": "Odměny Testnet jsou jen pro testy a nepřenášejí se do Mainnet. Tam začínají od nuly a ukládají se do účtu.",
    "Testnet inventory notice": "Shards a nákupy standardních lodí v Testnet jsou pro testy. Nepřenášejí se do Mainnet; zůstatek a koupená flotila začínají od nuly.",
    "Data unavailable. Retry.": "Data nejsou dostupná. Zkus znovu.",
    "Local rewards notice": "Místní odměny zůstanou na zařízení. Přihlas se pro ukládání nových do účtu Pi.",
    "Starter price notice": "Úvodní loď je zdarma. Cena platí za další loď.",
    "Twin rules": "Dvě souběžné střely. Aktivní 2 minuty po zapnutí.",
    "Rapid twin rules": "Dvě střely s rychlejší automatickou palbou. Aktivní 2 minuty.",
