    "Game saved. Offline backup unavailable.": "Hra uložena. Offline záloha není dostupná.",
    "Completed sections stay saved in your Pi account. An unfinished section restarts when you resume.": "Dokončené části zůstávají v účtu Pi. Nedokončená část při pokračování začne znovu.",
