    "Completed sections stay saved. Your remaining lives are kept when you leave.": "Dokončené části a zbývající životy se při odchodu uloží.",
    "Your completed sections and remaining lives stay saved. The unfinished section restarts; its points and Shards are discarded.": "Dokončené části a životy zůstávají uložené. Nedokončená část začne znovu; její body a Shards se zahodí.",
