    "Save failed. Game paused. Retry.": "Uložení selhalo. Hra zůstává pozastavená. Zkus znovu.",
    "Save unconfirmed. Retry or use confirmed save.": "Uložení nepotvrzeno. Zkus znovu nebo použij potvrzenou hru.",
    "Save unavailable. Please retry.": "Uložená hra není dostupná. Zkus znovu.",
    "Save unavailable. Local data unchanged. Retry sign-in.": "Uložená hra nedostupná. Místní data nezměněna. Přihlas se znovu.",
    "Save unavailable. Local data unchanged. Purchases locked.": "Uložená hra nedostupná. Místní data nezměněna. Nákupy zamčeny.",
    "Refresh inventory. Confirmed purchases will not repeat.": "Obnov inventář. Potvrzené nákupy se nebudou opakovat.",
    "Import unconfirmed. Check account inventory.": "Import nepotvrzen. Zkontroluj inventář účtu.",
    "Pending data set aside. Using the confirmed account save.": "Čekající data odložena. Používá se potvrzená hra účtu.",
    "You can import local Shards and Standard ships once, before your first account game. Pi purchases and records are excluded. Otherwise, local items stay on this device.": "Místní Shards a standardní lodě lze importovat jednou před první hrou účtu. Nákupy Pi a rekordy se nepřenášejí. Jinak předměty zůstanou na zařízení.",
    "Grey Scout is free; nine Standard hulls cost Shards. Other hulls are currently locked.": "Grey Scout je zdarma; devět standardních trupů stojí Shards. Ostatní jsou zamčené.",
    "Available only as a weapon pickup.": "Dostupné pouze jako sebraná zbraň.",
    "An older weapon selection is saved but no longer activates automatically. Every mission starts with the single laser.": "Starší volba zbraně je uložená, ale neaktivuje se automaticky. Každá mise začíná jedním laserem.",
    "1 Shard per target. Completion bonus added immediately.": "1 Shard za cíl. Bonus dokončení se přidá ihned.",
