    "EMP rules": "Једном по мисији. Зауставља непријатеље и паљбу на 7 секунди; уклања постојеће метке.",
    "Reinforced hull rules": "Трајни оклоп: +1 живот на почетку сваке мисије, без штита.",
    "Titanium rules": "Трајни оклоп: још 2 живота у свакој мисији. Додаје се ојачаном трупу.",
    "Advanced rules": "Трајно: двострука паљба и заштита од 1 пројектила по животу. Судари са бродовима требају штит.",
    "Elite rules": "Трајно: јачи двоструки ласер и заштита од 2 пројектила по животу. Судари требају штит. Потребан напредни степен.",
    "Payment": "Плаћање",
    "Boss stickers": "Значке шефова",
    "Bonus medals": "Бонус медаље",
